CREATE UNIQUE INDEX "IX_money_installments_PlanId_InstallmentNo" ON money_installments ("PlanId", "InstallmentNo");

CREATE INDEX "IX_money_installments_UserId_DueDate" ON money_installments ("UserId", "DueDate");

CREATE INDEX "IX_money_payments_InstallmentId" ON money_payments ("InstallmentId");

CREATE INDEX "IX_money_payments_UserId_PaidAt" ON money_payments ("UserId", "PaidAt");

