-- Move CPF/Document from user_profiles to users (centralized identity field).
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'users'
    ) THEN
        ALTER TABLE users ADD COLUMN IF NOT EXISTS "Document" character varying(11) NOT NULL DEFAULT '';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'user_profiles' AND column_name = 'Document'
    ) THEN
        UPDATE users
        SET "Document" = up."Document"
        FROM user_profiles up
        WHERE up."UserId" = users."Id" AND users."Document" = '' AND up."Document" <> '';

        ALTER TABLE user_profiles DROP COLUMN "Document";
    END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS "IX_users_Document" ON users ("Document") WHERE "Document" <> '';

-- Move AvatarUrl/City/State/Country from user_profiles to users (centralized profile data).
DO $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'users'
    ) THEN
        ALTER TABLE users ADD COLUMN IF NOT EXISTS "AvatarUrl" character varying(400);
        ALTER TABLE users ADD COLUMN IF NOT EXISTS "City" character varying(120);
        ALTER TABLE users ADD COLUMN IF NOT EXISTS "State" character varying(80);
        ALTER TABLE users ADD COLUMN IF NOT EXISTS "Country" character varying(120);
    END IF;

    IF EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'user_profiles' AND column_name = 'AvatarUrl'
    ) THEN
        UPDATE users
        SET "AvatarUrl" = up."AvatarUrl",
            "City" = up."City",
            "State" = up."State",
            "Country" = up."Country"
        FROM user_profiles up
        WHERE up."UserId" = users."Id";

        ALTER TABLE user_profiles DROP COLUMN "AvatarUrl";
        ALTER TABLE user_profiles DROP COLUMN "City";
        ALTER TABLE user_profiles DROP COLUMN "State";
        ALTER TABLE user_profiles DROP COLUMN "Country";
    END IF;
END $$;

