-- Enforce notification_settings / robot_settings as singleton tables: existing rows
-- (if any) keep their data, only the first row is flagged "Singleton" and a partial
-- unique index prevents a second row from ever being flagged.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'notification_settings') THEN
        ALTER TABLE notification_settings ADD COLUMN IF NOT EXISTS "Singleton" boolean NOT NULL DEFAULT FALSE;
        UPDATE notification_settings SET "Singleton" = TRUE WHERE "Id" = (SELECT MIN("Id") FROM notification_settings) AND NOT "Singleton";
        ALTER TABLE notification_settings ALTER COLUMN "Singleton" SET DEFAULT TRUE;
    END IF;

    IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'robot_settings') THEN
        ALTER TABLE robot_settings ADD COLUMN IF NOT EXISTS "Singleton" boolean NOT NULL DEFAULT FALSE;
        UPDATE robot_settings SET "Singleton" = TRUE WHERE "Id" = (SELECT MIN("Id") FROM robot_settings) AND NOT "Singleton";
        ALTER TABLE robot_settings ALTER COLUMN "Singleton" SET DEFAULT TRUE;
    END IF;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS "IX_notification_settings_Singleton" ON notification_settings ("Singleton") WHERE "Singleton";
CREATE UNIQUE INDEX IF NOT EXISTS "IX_robot_settings_Singleton" ON robot_settings ("Singleton") WHERE "Singleton";

-- Convert card_brands.Id / payment_methods.Id to identity columns, matching the
-- GENERATED BY DEFAULT AS IDENTITY strategy used by other lookup tables (e.g. institutions).
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_attribute
        WHERE attrelid = 'card_brands'::regclass AND attname = 'Id' AND attidentity <> ''
    ) THEN
        ALTER TABLE card_brands ALTER COLUMN "Id" ADD GENERATED BY DEFAULT AS IDENTITY;
        PERFORM setval(pg_get_serial_sequence('card_brands', 'Id'), COALESCE((SELECT MAX("Id") FROM card_brands), 0) + 1, false);
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_attribute
        WHERE attrelid = 'payment_methods'::regclass AND attname = 'Id' AND attidentity <> ''
    ) THEN
        ALTER TABLE payment_methods ALTER COLUMN "Id" ADD GENERATED BY DEFAULT AS IDENTITY;
        PERFORM setval(pg_get_serial_sequence('payment_methods', 'Id'), COALESCE((SELECT MAX("Id") FROM payment_methods), 0) + 1, false);
    END IF;
END $$;
